/* Version script for the consumer's .so: the only symbol the dynamic linker sees is JNI_OnLoad (lld refuses a global
   name that the library does not define, so JNI_OnUnload is not listed; the runtime has no use for it).
   -fvisibility=hidden already hides our own code; this also hides what header-only code of the C++ library
   (std::shared_ptr, std::string, operator new) emits with default visibility. */
{
    global:
        JNI_OnLoad;
    local:
        *;
};
